tools.example:
msgs, ok = hfss.validate_full_design(ports=2)
if not ok:
    for m in msgs:
        print(m)
    raise SystemExit("Design validation failed")
hfss.analyze()

for v in list(hfss.variable_manager.independent_design_variable_names):
    if not hfss.variable_manager.is_used(v):
        hfss.delete_variable(v)
hfss.hidden_variable("internal_scale", True)
hfss.read_only_variable("$sub_h", True)

if not hfss.dataset_exists("$meas_er"):
    hfss.import_dataset1d("C:/data/meas_er.tab", name="$meas_er", is_project_dataset=True)
for n, ds in hfss.project_datasets.items():
    print(n, len(ds.x))

mats = hfss.materials
if not mats.exists_material("Rogers RO4350B (tm)"):
    raise ValueError("library material missing")
ro = mats["Rogers RO4350B (tm)"]
print(ro.permittivity.value, ro.dielectric_loss_tangent.value)
print(mats.conductors)
for m in mats.material_keys:
    if m not in mats.get_used_project_material_names():
        print("unused:", m)
